create table r_cfg_instrument_pool_props(key_instrument_id string comment '标的ID',interotc_code string comment '报价系统代码',interotc_underlying_type string comment '报价系统标的类型',interotc_underlying_category string comment '报价系统标的小类',trading_place string comment '报价系统标的交易场所',interotc_name string comment '报价系统名称',report_to string comment '报备场所',last_trade_date string comment '最后交易日',price_exchange string comment '交易所',price_publish_organ string comment '收盘价的公布机构',price_website string comment '收盘价的参考网页',otc_underlying_type string comment 'OTC标的类型',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',l string comment '保证金L参数',h string comment '保证金H参数',data_time string comment '数据时间',risk_level string comment '证券风险等级',key_pool_id string comment '标的池ID') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
